#!/usr/bin/env node
/**
 * Records a conformance proof into the registry entry (src/registry.ts requires
 * one at admission).
 *
 * The proof is generated by running the suite against the committed adapter and
 * fixtures — never written by hand — so the entry's evidence corresponds to an
 * actual run, with its timestamp and connector version.
 *
 * Usage: npm run record:conformance
 * Exit codes: 0 recorded, 1 the suite did not pass, 2 the entry is unusable.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { runConformance } from '../src/conformance.js';
import { buildGitHubHarness } from '../test/github-harness.js';

const ENTRY = fileURLToPath(new URL('../registry/entries/github-repository.json', import.meta.url));

async function main(): Promise<number> {
  const { harness } = buildGitHubHarness();
  const proof = await runConformance(harness);

  console.log(`checks run: ${proof.checks.length}`);
  if (!proof.passed) {
    console.error('the suite did not pass; refusing to record a proof:');
    for (const check of proof.checks.filter((result) => !result.passed)) {
      console.error(`  - ${check.name}: ${check.detail ?? 'no detail'}`);
    }
    return 1;
  }

  let entry: { conformance?: unknown; [key: string]: unknown };
  try {
    entry = JSON.parse(readFileSync(ENTRY, 'utf8')) as typeof entry;
  } catch (error) {
    console.error(
      `could not read ${ENTRY}: ${error instanceof Error ? error.message : String(error)}`,
    );
    return 2;
  }

  const previous = entry.conformance as { ranAt?: string } | undefined;
  entry.conformance = proof;
  writeFileSync(ENTRY, `${JSON.stringify(entry, null, 2)}\n`, 'utf8');

  console.log(
    `recorded proof for ${proof.capabilityId}/${proof.providerId}@${proof.connectorVersion} at ${proof.ranAt}` +
      (previous?.ranAt ? ` (replacing ${previous.ranAt})` : ''),
  );
  return 0;
}

main().then(
  (code) => {
    process.exitCode = code;
  },
  (error: unknown) => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  },
);
